css:
.omd [data-omd-part="sidebar"] { background: var(--omd-sidebar); color: var(--omd-text); }
.omd [data-omd-part="conversation"], .omd [data-omd-part="header"] { background: var(--omd-bg); color: var(--omd-text); }
.omd [data-omd-part="composer"] {
  background: var(--omd-surface); border: 1px solid var(--omd-border);
  border-radius: var(--omd-radius-composer); box-shadow: var(--omd-shadow);
}
.omd [data-omd-part="composer"]:hover { border-color: var(--omd-border-strong); box-shadow: var(--omd-shadow-hover); }
.omd [data-omd-part="composer"]:focus-within { border-color: var(--omd-border-strong); box-shadow: var(--omd-shadow-focus); }
.omd [data-omd-part="message-user"] { background: var(--omd-user-bg); color: var(--omd-text); border: 0; border-radius: 18px; font-family: var(--omd-font-ui); }
.omd [data-omd-part="send"] { background: var(--omd-button-bg); color: var(--omd-button-fg); border: 0; border-radius: 8px; box-shadow: none; }
.omd [data-omd-part="send"]:disabled { background: var(--omd-selected); color: var(--omd-muted); }
.omd [data-omd-part="form-control"] { background: var(--omd-surface); color: var(--omd-text); border: 1px solid var(--omd-border); border-radius: 8px; box-shadow: none; }
.omd [data-omd-part="button"]:focus-visible, .omd [data-omd-part="form-control"]:focus-visible { outline: 2px solid var(--omd-focus); outline-offset: 2px; }
.omd [data-omd-part="dialog"], .omd [data-omd-part="menu"] { background: var(--omd-surface-solid); color: var(--omd-text); border: 1px solid var(--omd-border); border-radius: 12px; box-shadow: var(--omd-shadow-popover); }
.omd [data-omd-part="settings-nav-item"][data-omd-state="selected"] { background: var(--omd-selected); color: var(--omd-text); font-weight: 500; }
.omd [data-omd-part="process-toggle"] { color: var(--omd-muted); background: transparent; border: 0; }
.omd [data-omd-part="tool-group"] { background: transparent; border-color: var(--omd-border); }
.omd [data-omd-part="code-block"] { background: var(--omd-code-bg); border: 1px solid var(--omd-border); border-radius: 12px; }
.omd [data-omd-part="code-inline"] { background: var(--omd-code-bg); border-radius: 4px; }
.omd [data-omd-part="workbench"], .omd [data-omd-part="settings-content"] { background: var(--omd-bg); color: var(--omd-text); }
